 242	A measurement that is consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement} is $0$-consistent with itself on the same state under the singleton distribution, and vice versa: if $\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = 1$, then $M_a \ot \Id\, \ket{\psi} = \Id \ot M_a\, \ket{\psi}$ for every $a$, by the equality case of the Cauchy--Schwarz inequality applied outcome by outcome.
 243	
 244	% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:257-274) states this
 245	% definition for pairs of POVMs but applies the relation to arbitrary operator families:
 246	% to plain operators at 06:313-330, to sets of matrices at 06:364-380, and to products and
 247	% commutators, compared against the zero family, at 06:409-445. The general form below,
 248	% for arbitrary finite families of operators, is the one of the NEEXP source
 249	% (references/neexp-paper/05_quantum_preliminaries.tex:385-391), from which the distance
 250	% calculus is imported; the POVM case is singled out after the display.
 251	\begin{definition}[State-dependent distance between operator families]\label{def:povm-distance}
 252		\uses{def:povm-conventions, def:state-distance}
 253		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H$ be a quantum state, and for all $x \in \mathcal X$ let $\{M^x_a\}_{a \in \mathcal A}$ and $\{N^x_a\}_{a \in \mathcal A}$ be two families of linear operators on $\mathcal H$. We say that \emph{$\{M^x_a\}$ and $\{N^x_a\}$ are $\delta$-close on state $\ket{\psi}$ and under distribution $\mu$} if
 254		\[
 255			\E_{x \sim \mu} \sum_a \lVert (M^x_a - N^x_a)\, \ket{\psi} \rVert^2 \le O(\delta)\,,
 256		\]
 257		and we write $M^x_a \approx_\delta N^x_a$ to denote this when the state $\ket{\psi}$ and the distribution $\mu$ are clear from context. This distance is referred to as the \emph{state-dependent} distance. The principal case is that in which $\{M^x_a\}$ and $\{N^x_a\}$ are POVMs on $\mathcal H$, and we then speak of the state-dependent distance between the POVMs; but the relation is used for arbitrary operator families --- for instance for products of measurement operators, or for commutators compared against the identically zero family, as in Lemma~\ref{lem:commutation-analysis} below.
 258	\end{definition}
 259	
 260	\begin{definition}[Distance between strategies]\label{def:strategy-distance}
 261		\lean{MIPStarRE.QPBT.AreCloseStrategies}
 262		\leanok
 263		\uses{def:tensor-product-strategy, def:state-distance, def:povm-distance}
 264		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a nonlocal game and let $\mathcal S = (\psi, A, B)$ and $\mathcal S' = (\psi', A', B')$ be strategies for $\mathfrak G$. For $\delta \in [0,1]$ we say that \emph{$\mathcal S$ is $\delta$-close to $\mathcal S'$} if the following conditions hold.
 265		\begin{enumerate}
 266			\item The states $\ket{\psi}, \ket{\psi'}$ are states in the same Hilbert space $\mathcal H_A \ot \mathcal H_B$ and are $\delta$-close.
 267			\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
 268		\end{enumerate}
 269	\end{definition}
